using System.ComponentModel;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Build the IChatClient via MEAI ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Instantiate tools ---
var notebook = new Notebook();
var researchTools = new ResearchTools(notebook);

// --- Create the agent ---
var agent = new ChatClientAgent(chatClient, new()
{
    Instructions = """
        You are a research assistant. When the user gives you a topic:
        1. Search the web for relevant information (make 2-3 varied searches).
        2. Save key findings as notes with descriptive titles.
        3. After gathering enough information, produce a final summary that
           synthesizes all your notes into a coherent briefing.
        Always cite the sources you found.
        """,
});

// --- Run the agent loop ---
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.Error.WriteLine("No topic provided.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and summarize your findings:\n\n{topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Tools = [.. AIFunctionFactory.Create(researchTools)],
    ChatOptions = new() { Temperature = 0f },
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();

// Print the notebook
if (notebook.Notes.Count > 0)
{
    Console.WriteLine("\n--- Saved Notes ---");
    foreach (var note in notebook.Notes)
    {
        Console.WriteLine($"\n## {note.Title}");
        Console.WriteLine(note.Content);
    }
}

// === Tool implementations ===

/// <summary>Stores research notes collected by the agent.</summary>
public sealed class Notebook
{
    public List<Note> Notes { get; } = [];

    public sealed record Note(string Title, string Content, DateTime SavedAt);
}

/// <summary>Tools available to the research agent.</summary>
public sealed class ResearchTools(Notebook notebook)
{
    private static readonly HttpClient s_http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a query. Returns a JSON array of search results with title, link, and snippet.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        try
        {
            // Uses the DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await s_http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<object>();

            // Abstract text (main answer)
            if (root.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
            {
                var source = root.TryGetProperty("AbstractURL", out var aUrl) ? aUrl.GetString() : "";
                results.Add(new { title = "Summary", link = source, snippet = abstractText });
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray())
                {
                    if (results.Count >= maxResults) break;

                    if (item.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                    {
                        var link = item.TryGetProperty("FirstURL", out var u) ? u.GetString() : "";
                        results.Add(new { title = t[..Math.Min(80, t.Length)], link, snippet = t });
                    }
                }
            }

            if (results.Count == 0)
            {
                return JsonSerializer.Serialize(new { message = $"No results found for '{query}'. Try rephrasing." });
            }

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return JsonSerializer.Serialize(new { error = $"Search failed: {ex.Message}" });
        }
    }

    [Description("Fetch the content of a web page and return its text (truncated to ~4000 chars).")]
    public async Task<string> FetchWebPage(
        [Description("The full URL of the page to fetch")] string url)
    {
        try
        {
            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.Add("User-Agent", "ResearchAgent/1.0");
            var response = await s_http.SendAsync(request);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync();

            // Crude HTML-to-text: strip tags, collapse whitespace
            var text = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
            text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ").Trim();

            const int maxLen = 4000;
            if (text.Length > maxLen)
                text = text[..maxLen] + "... [truncated]";

            return text;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    [Description("Save a research note to the notebook for later summarization.")]
    public string SaveNote(
        [Description("A short descriptive title for the note")] string title,
        [Description("The content/findings to save")] string content)
    {
        notebook.Notes.Add(new Notebook.Note(title, content, DateTime.UtcNow));
        return $"Note saved: '{title}' ({notebook.Notes.Count} total notes)";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (notebook.Notes.Count == 0)
            return "No notes saved yet.";

        return JsonSerializer.Serialize(
            notebook.Notes.Select(n => new { n.Title, n.Content, n.SavedAt }),
            new JsonSerializerOptions { WriteIndented = true });
    }
}

